import {installHoldNavigation,holdDuration} from './hold.mjs';
import {parseCockpitCSV,csvSyncs,resolveEDL,FRAME_RATES,tcFrames,framesTC} from './edl.mjs';
import {validateInterview,freshSession,stepsFor,start,pause,resume,move,finish,event,addSync,activeMs,stepSpent,fmt,metrics,protocolRows,csvFor,pack,unpack,validateSession,recordingAt,visualTiming} from './core.mjs';
const $=id=>document.getElementById(id),scope=new URL('.',location.href).pathname;
const KEY=`interview-cockpit:v1:${scope}`,PREF=`${KEY}:prefs`,writer=crypto.randomUUID?.()??Math.random().toString(36);
let session,revision=0,foreign=false,storageFailed=false,audioContext,wakeLock,toastTimer,noteOpen=false,followOpen=true,importCandidate=null;
let prefs={fontSize:42,light:false,focus:false,wake:true,holdNav:true,holdMs:600,haptics:true};
const palette={mint:['#99dfc3','153,223,195'],blue:['#a8cefb','168,206,251'],amber:['#f1ca8d','241,202,141'],violet:['#c6b4f3','198,180,243'],rose:['#f2b6c6','242,182,198']};
const lightPalette={mint:['#216e59','33,110,89'],blue:['#275c99','39,92,153'],amber:['#895700','137,87,0'],violet:['#6c409b','108,64,155'],rose:['#9b365a','155,54,90']};
function escapeHTML(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function rich(text){return escapeHTML(text).split('**').map((part,i)=>i%2?`<strong>${part}</strong>`:part).join('');}
function plain(text){return String(text).replaceAll('**','');}
function localTime(t){return new Date(t).toLocaleTimeString('de-CH',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function notify(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400);}
function storageWarning(message){storageFailed=true;document.body.classList.add('has-error');$('saved').textContent='Sicherung prüfen';$('storage-alert').hidden=false;$('storage-alert').textContent=message;}
function readStore(){let candidates=[],had=false;for(const key of [KEY,KEY+':backup']){const raw=localStorage.getItem(key);if(raw){had=true;const p=unpack(raw);if(p)candidates.push(p);}}candidates.sort((a,b)=>b.revision-a.revision);return {value:candidates[0],damaged:had&&!candidates.length};}
function save(){
 if(foreign)return false;
 try{const previous=readStore();if(previous.value&&previous.value.writer!==writer&&previous.value.revision>revision){foreign=true;lockWarning();return false;}
  revision++;const data=pack(session,revision,writer);localStorage.setItem(KEY+':backup',data);localStorage.setItem(KEY,data);storageFailed=false;document.body.classList.remove('has-error');$('saved').textContent='Lokal gesichert';$('storage-alert').hidden=true;return true;
 }catch{storageWarning('Die lokale Sicherung ist nicht verfügbar. Exportiere jetzt ein Sitzungs-Backup und behalte diese Seite geöffnet.');return false;}
}
function lockWarning(){$('storage-alert').hidden=false;$('storage-alert').textContent='Dieses Interview wurde in einem anderen Tab geändert. Dieser Tab ist gesperrt. Lade ihn neu, um den aktuellen Stand zu übernehmen.';document.querySelectorAll('#live button, #setup button').forEach(x=>x.disabled=true);}
function mutate(fn){if(foreign){notify('Bitte diesen Tab neu laden.');return;}fn();save();render();}
function setAccent(color){const tint=sectionColor(color);document.documentElement.style.setProperty('--section-color',tint);document.documentElement.style.setProperty('--section-rgb',rgb(tint));const [c,r]=prefs.focus?['#ffffff','255,255,255']:(prefs.light?lightPalette:palette)[color]??palette.mint;document.documentElement.style.setProperty('--accent',c);document.documentElement.style.setProperty('--accent-rgb',r);}
function applyPrefs(){holdNavigation.cancel();document.body.classList.toggle('hold-enabled',prefs.focus&&prefs.holdNav);document.body.classList.toggle('light',prefs.light);document.body.classList.toggle('focus',prefs.focus);document.documentElement.style.setProperty('--question-size',`${prefs.fontSize}px`);$('focus-btn').setAttribute('aria-pressed',String(prefs.focus));$('focus-btn').setAttribute('aria-label',prefs.focus?'Vollbild beenden':'Vollbild / Fokusmodus');$('focus-btn').title=prefs.focus?'Vollbild beenden':'Vollbild / Fokusmodus';$('focus-title').textContent=session.interview.guest||session.interview.title;setAccent(stepsFor(session.interview)[session.current].color);requestAnimationFrame(fitFocusQuestion);}
function fitFocusQuestion(){
 if(!prefs.focus||!session||!['running','paused'].includes(session.status))return;
 const heading=$('question-text'),height=window.visualViewport?.height??window.innerHeight;
 const extra=document.querySelector('.followup-area').getBoundingClientRect().height+($('hint').hidden?0:$('hint').getBoundingClientRect().height)+document.querySelector('.under-card').getBoundingClientRect().height+document.querySelector('.navigation').getBoundingClientRect().height+($('note-area').hidden?0:$('note-area').getBoundingClientRect().height)+72;
 const available=Math.max(100,height-heading.getBoundingClientRect().top-extra);
 let low=Math.max(30,prefs.fontSize*.8),high=Math.min(140,prefs.fontSize*2.8);
 for(let i=0;i<8;i++){const size=(low+high)/2;heading.style.setProperty('--focus-size',size+'px');if(heading.getBoundingClientRect().height<=available)low=size;else high=size;}
 heading.style.setProperty('--focus-size',Math.floor(low)+'px');
}
document.fonts.ready.then(()=>requestAnimationFrame(fitFocusQuestion));
window.addEventListener('resize',()=>requestAnimationFrame(fitFocusQuestion));
window.visualViewport?.addEventListener('resize',()=>requestAnimationFrame(fitFocusQuestion));
async function setFocus(enabled){
 prefs.focus=enabled;savePrefs();
 try{if(enabled&&!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(!enabled&&document.fullscreenElement)await document.exitFullscreen();}catch{ /* Safari may only support the viewport-based focus layout. */ }
}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&prefs.focus){prefs.focus=false;savePrefs();const checkbox=$('focus-mode');if(checkbox)checkbox.checked=false;}});
function savePrefs(){try{localStorage.setItem(PREF,JSON.stringify(prefs));}catch{}applyPrefs();tick();}
function modal(title,html){holdNavigation.cancel();$('modal-title').textContent=title;$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function closeModal(){$('modal').close();}
function button(id,fn){$(id)?.addEventListener('click',fn);}
function completedIds(){return new Set(session.visits.filter(v=>v.end!==null).map(v=>v.stepId));}
function renderNav(){const done=completedIds(),steps=stepsFor(session.interview),all=steps.filter(x=>x.kind==='question');$('question-count').textContent=`${all.length} Fragen`;$('interview-title').textContent=session.interview.title;$('guest').textContent=session.interview.guest||'Dein Gespräch';$('section-nav').innerHTML=session.interview.sections.map(s=>{const count=s.questions.filter(q=>done.has(q.id)).length,current=steps[session.current].sectionId===s.id;return `<button class="nav-section ${current?'current':''} ${count===s.questions.length?'complete':''}" data-section="${escapeHTML(s.id)}" ${current?'aria-current="step"':''}><span class="nav-line"><span class="section-letter">${count===s.questions.length?'✓':escapeHTML(s.id)}</span><span class="nav-name">${escapeHTML(s.title)}</span></span><span class="nav-sub"><span>${count} / ${s.questions.length} Fragen</span><span>${Math.round(s.questions.reduce((n,q)=>n+q.seconds,0)/60)} Min.</span></span></button>`;}).join('');
 $('section-nav').querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>jumpMenu(b.dataset.section));}
function renderSetup(){const total=stepsFor(session.interview).reduce((n,s)=>n+s.seconds,0),count=session.interview.sections.reduce((n,s)=>n+s.questions.length,0);$('setup').innerHTML=`<p class="kicker">BEREIT FÜR EIN GUTES GESPRÄCH</p><h2>Ganz beim Gegenüber.<br><span style="color:var(--accent)">Den Leitfaden im Blick.</span></h2><p>Eine Frage nach der anderen. Klare Übergänge, ein ruhiger Zeitplan und Marker für den späteren Schnitt.</p><div class="setup-grid"><div class="setup-tile"><strong>${Math.round(total/60)} Minuten</strong><p>Mit Einstieg und Abschluss</p></div><div class="setup-tile"><strong>${count} Leitfragen</strong><p>${session.interview.sections.length} Themenbereiche · ${escapeHTML(session.interview.guest||'Eigenes Interview')}</p></div></div><label class="checkline"><input type="checkbox" id="consent"><span>Die Erlaubnis für Aufnahme und Verwendung ist geklärt.</span></label><label class="checkline"><input type="checkbox" id="record-ready"><span>Ton, Bild, Speicher und Akku sind geprüft.</span></label><button id="start-btn" class="primary" disabled>Interview starten <span>→</span></button><p class="setup-tip">Die Uhr beginnt mit dem Einstieg. Starte danach deine Aufnahme und setze einen <strong>Sync-Punkt</strong>. Die App selbst nimmt kein Audio oder Video auf.</p><p class="setup-tip" id="setup-offline">Offline-Modus wird vorbereitet …</p><div class="setup-tools"><button class="secondary" id="load-setup">JSON laden / Backup öffnen</button><button class="text-button" id="demo-tone">Sync-Ton testen ♪</button><button class="text-button" id="help-setup">Kurzanleitung →</button></div>`;
 const check=()=>{$('start-btn').disabled=!$('consent').checked||!$('record-ready').checked;};$('consent').onchange=check;$('record-ready').onchange=check;
 button('start-btn',()=>{mutate(()=>{start(session);event(session,'consent_confirmed');});acquireWake();navigator.storage?.persist?.().catch(()=>{});});button('load-setup',showLibrary);button('help-setup',showHelp);button('demo-tone',()=>playSignal(false));}
function render(){const steps=stepsFor(session.interview),q=steps[session.current];applyPrefs();renderNav();$('setup').hidden=session.status!=='ready';$('live').hidden=!['running','paused'].includes(session.status);$('finished').hidden=session.status!=='ended';if($('live').hidden)$('focus-handoff-edge').hidden=true;if(session.status==='ready'){renderSetup();if($('setup-offline'))$('setup-offline').textContent=$('offline-state').textContent;}if(session.status==='ended'){renderFinished();return;}if(session.status==='ready')return;
 const count=steps.filter(x=>x.kind==='question').length,done=completedIds(),completed=steps.filter(x=>x.kind==='question'&&done.has(x.id)).length,visits=session.visits.filter(v=>v.stepId===q.id).length;
 $('section-label').textContent=q.kind==='question'?`${q.sectionId} · ${q.sectionTitle}`:q.sectionTitle;$('essential').hidden=!q.essential;$('visit-info').textContent=visits>1?`${visits}. Durchgang · Zeiten werden addiert`:'';$('transition').textContent=q.transition||'Schauen wir auf einen weiteren Aspekt.';$('focus-transition').textContent=$('transition').textContent;$('question-text').innerHTML=rich(q.text);$('hint').textContent=q.hint;$('hint').hidden=!q.hint;
 $('followups').innerHTML=q.followUps.map(f=>`<p class="followup-item">${rich(f)}</p>`).join('');$('followups').hidden=!followOpen;$('followup-toggle').hidden=!q.followUps.length;$('followup-toggle').setAttribute('aria-expanded',String(followOpen));$('followup-toggle').querySelector('span').textContent=followOpen?'−':'＋';
 $('position-label').textContent=q.kind==='question'?`Frage ${q.number} von ${count} · Bereich ${q.sectionId} / ${session.interview.sections.length}`:q.kind==='intro'?'Einstieg · Vor der ersten Frage':'Abschluss · Nach der letzten Frage';$('progress-label').textContent=`${completed} von ${count} abgeschlossen`;$('progress-fill').style.width=`${completed/count*100}%`;$('progress-bar').setAttribute('aria-valuenow',String(Math.round(completed/count*100)));
 renderSectionProgress(q,done);$('back-btn').disabled=session.current===0;$('next-btn').innerHTML=session.current===steps.length-1?'Interview beenden <span>✓</span>':session.current===0?'Erste Frage <span>→</span>':'Nächste Frage <span>→</span>';$('next-preview').textContent=steps[session.current+1]?plain(steps[session.current+1].text):'Aufnahme beenden und Protokoll exportieren';$('question-note').value=session.notes[q.id]??'';$('note-area').hidden=!noteOpen;$('marker-count').textContent=`${session.events.filter(e=>e.type==='marker').length} Marker`;$('pause-btn').innerHTML=session.status==='paused'?'Weiter':'Pause';$('focus-pause-btn').textContent=session.status==='paused'?'Weiter':'Pause';$('focus-pause-btn').setAttribute('aria-pressed',String(session.status==='paused'));tick();if(foreign)lockWarning();}
function tick(){if(!session||!['running','paused'].includes(session.status))return;const m=metrics(session),q=stepsFor(session.interview)[session.current];$('total-elapsed').textContent=fmt(m.active);$('total-target').textContent=`/ ${fmt(m.total)}`;$('total-status').textContent=m.remaining>=0?`${fmt(m.remaining)} bis zum geplanten Ende`:`${fmt(-m.remaining)} über dem Gesamtbudget`;$('total-status').className=`time-caption ${m.remaining<0?'danger':''}`;$('question-elapsed').textContent=fmt(m.spent);$('question-target').textContent=`/ ${fmt(q.seconds*1000)}`;$('question-status').textContent=m.stepRemaining>=0?`${fmt(m.stepRemaining)} im Fragenbudget`:`${fmt(-m.stepRemaining)} über Fragenbudget`;$('question-status').className=`time-caption ${m.stepRemaining<0?'amber':''}`;
 // Compare completed time + elapsed part of current step with its cumulative planned budget.
 const scheduleDelta=m.active-m.plannedBefore-Math.min(m.spent,q.seconds*1000),tol=15000;
 const visual=visualTiming(session);
 $('focus-total-time').textContent=fmt(m.active)+' / '+fmt(m.total);
 $('focus-question-time').textContent=fmt(m.spent)+' / '+fmt(q.seconds*1000);
 for(const [kind,delta,label,ratio] of [['total',visual.scheduleDelta,visual.scheduleLabel,visual.totalRatio],['question',visual.questionDelta,visual.questionLabel,visual.questionRatio]]){
  const sign=delta>0?'late':delta<0?'early':'on-time';
  $('focus-'+kind+'-delta').textContent=label;$('focus-'+kind+'-delta').className='time-delta '+sign;
  $('focus-'+kind+'-fill').style.width=(ratio*100)+'%';$('focus-'+kind+'-fill').className=sign;
  $('focus-'+kind+'-meter').setAttribute('aria-valuenow',String(Math.round(ratio*100)));
  $('focus-'+kind+'-meter').setAttribute('aria-valuetext',kind==='total'?fmt(m.active)+' von '+fmt(m.total)+', Zeitplan '+label:fmt(m.spent)+' von '+fmt(q.seconds*1000)+', Budget '+label);
 }
 $('focus-plan-tick').style.left=(visual.plannedRatio*100)+'%';

 $('pace-value').textContent=Math.abs(scheduleDelta)<=tol?'Im Plan':`${fmt(Math.abs(scheduleDelta))} ${scheduleDelta>0?'später':'früher'}`;$('pace-value').className=scheduleDelta>tol?'amber':'';$('pace-caption').textContent='Gegenüber dem geplanten Ablauf';$('status-label').textContent=session.status==='paused'?'INTERVIEW PAUSIERT':'INTERVIEW LÄUFT';$('live-dot').style.background=session.status==='paused'?'#f1ca8d':'#99dfc3';}
function navigate(index){mutate(()=>move(session,index));noteOpen=false;render();window.scrollTo({top:0,behavior:'instant'});}
function jumpMenu(sectionId){const steps=stepsFor(session.interview),qs=steps.map((q,i)=>({...q,index:i})).filter(q=>q.sectionId===sectionId),done=completedIds();modal('Themenbereich ansehen',`<p class="modal-copy">${session.status==='ready'?'Die Reihenfolge beginnt mit dem Einstieg.':'Ein Sprung beendet die aktuelle Frage und startet einen neuen protokollierten Abschnitt. Rücksprünge bleiben als eigener Durchgang erhalten.'}</p>${qs.map(q=>`<button class="nav-section" data-jump="${q.index}" style="border-color:var(--line);margin-bottom:8px"><span class="nav-line"><span class="section-letter">${q.number}</span><span class="nav-name">${rich(q.text)}</span></span><span class="nav-sub">${fmt(q.seconds*1000)} geplant ${done.has(q.id)?'· bereits besucht':''}</span></button>`).join('')}`);$('modal-body').querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{if(['running','paused'].includes(session.status)){closeModal();navigate(Number(b.dataset.jump));}else notify('Fragenwechsel sind während des Interviews möglich.');});}
function confirmFinish(){modal('Interview abschliessen?',`<p class="modal-copy">Die aktuelle Frage erhält einen Endzeitstempel und die Interviewuhr stoppt. Deine Aufnahme beendest du auf dem Aufnahmegerät separat.</p><div class="button-row"><button id="confirm-finish" class="primary">Abschliessen & Protokoll</button><button id="cancel-finish" class="secondary">Zurück zum Gespräch</button></div>`);button('confirm-finish',()=>{mutate(()=>finish(session));releaseWake();closeModal();});button('cancel-finish',closeModal);}
function renderFinished(){const m=metrics(session),done=completedIds(),n=stepsFor(session.interview).filter(q=>q.kind==='question'&&done.has(q.id)).length;$('finished').innerHTML=`<section class="finish-card"><span class="finish-icon">✓</span><p class="eyebrow">GESPRÄCH ABGESCHLOSSEN</p><h2>Die Gedanken bleiben.<br>Die Stellen findest du wieder.</h2><p>${escapeHTML(session.interview.guest||session.interview.title)} · ${session.endedAt?new Date(session.endedAt).toLocaleDateString('de-CH'):''}</p><div class="finish-stats"><div><strong>${fmt(m.active)}</strong><span>Aktive Interviewzeit</span></div><div><strong>${n}</strong><span>Leitfragen besucht</span></div><div><strong>${session.events.filter(e=>e.type==='marker').length}</strong><span>Clip-Marker</span></div></div><div class="button-row"><button id="finish-log" class="primary">Protokoll öffnen →</button><button id="finish-backup" class="secondary">Sitzungs-Backup sichern</button></div><p class="setup-tip">Exportiere das Protokoll jetzt. Es enthält Fragen, Beginn und Ende, Notizen, Pausen und Synchronisationspunkte.</p><div class="button-row"><button id="new-session" class="text-button">Neues Interview vorbereiten →</button></div></section>`;button('finish-log',showLog);button('finish-backup',()=>exportFile('backup'));button('new-session',()=>confirmNew(session.interview));}
function mark(){if(!['running','paused'].includes(session.status))return;mutate(()=>event(session,'marker',Date.now(),{label:`Clip ${session.events.filter(e=>e.type==='marker').length+1}`}));notify(`⚑ Clip ${session.events.filter(e=>e.type==='marker').length} bei ${fmt(activeMs(session))} markiert`);}
function textProtocol(){const rows=protocolRows(session),lines=[`INTERVIEWPROTOKOLL`,session.interview.title,session.interview.guest,`Erstellt: ${new Date().toLocaleString('de-CH')}`,`Status: ${session.status}`,`Aktive Interviewzeit: ${fmt(activeMs(session))}`,'','Zeitbasis: Uhrzeit mit Zeitzone im JSON/CSV. Interviewzeit ohne explizite Pausen. Aufnahmezeit läuft über Pausen weiter. Aufnahmezeiten gelten erst ab dem jeweiligen Sync-Punkt und sind Orientierungswerte. Frühere Einträge bleiben ohne Aufnahmezeit.',''];for(const r of rows){const rec=r.recordingSeconds===null?'ohne Sync':`${fmt(r.recordingSeconds*1000)} Aufnahme (${r.syncId})`;lines.push(`${localTime(r.at)} | ${fmt(r.activeMs)} Interview | ${rec} | ${r.type==='question'?'FRAGE':eventName(r.type).toUpperCase()}`,`${r.section} · ${r.label}`);if(r.type==='question')lines.push(`Ende: ${r.end?localTime(r.end):'offen'} | Aktiv: ${fmt(r.durationMs)}${r.recordingEndSeconds!=null?' | Aufnahme Ende: '+fmt(r.recordingEndSeconds*1000):''}`);if(r.note)lines.push(`Notiz: ${r.note}`);lines.push('');}return lines.join('\n');}
const eventNames={start:'Interview gestartet',finish:'Interview beendet',pause:'Pause',resume:'Fortgesetzt',question_change:'Fragenwechsel',sync:'Sync-Punkt',sync_offset_changed:'Videozeit korrigiert',screen_hidden:'Bildschirm ausgeblendet',screen_visible:'Bildschirm wieder sichtbar',consent_confirmed:'Einverständnis bestätigt'};
const eventName=t=>eventNames[t]??t;
const MIME={backup:'application/json',json:'application/json',csv:'text/csv;charset=utf-8',txt:'text/plain;charset=utf-8',template:'application/json'};
function fileData(type){if(type==='backup'){const snapshot=structuredClone(session),now=Date.now();if(snapshot.status==='running')pause(snapshot,now);return JSON.stringify({format:'interview-cockpit-session',version:1,exportedAt:new Date(now).toISOString(),session:snapshot},null,2);}if(type==='json')return JSON.stringify({format:'interview-cockpit-protocol',version:1,interview:session.interview,status:session.status,exportedAt:new Date().toISOString(),sessionId:session.id,syncs:session.syncs,runs:session.runs,events:session.events,rows:protocolRows(session)},null,2);if(type==='csv')return csvFor(session);if(type==='template')return JSON.stringify(session.interview,null,2);return textProtocol();}
async function exportFile(type,share=false){try{const data=fileData(type),base=(session.interview.guest||session.interview.title).replace(/[^\p{L}\p{N}-]+/gu,'_').slice(0,65),date=new Date().toISOString().slice(0,10),ext=['csv','txt'].includes(type)?type:'json',name=`${base}_${type}_${date}.${ext}`,blob=new Blob([data],{type:MIME[type]});if(share&&navigator.canShare){const f=new File([blob],name,{type:MIME[type]});if(navigator.canShare({files:[f]})){await navigator.share({files:[f],title:'Interviewprotokoll'});return;}}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Export erstellt. Auf dem iPad bei Bedarf in Dateien sichern.');}catch(e){if(e.name!=='AbortError')notify('Export fehlgeschlagen. Bitte erneut versuchen.');}}
function showLog(){const rows=protocolRows(session),sync=session.syncs.at(-1);modal('Dein Schnittprotokoll',`<p class="modal-copy">Fragenwechsel, Marker und Pausen. <strong>Interviewzeit</strong> ohne explizite Pausen; <strong>Aufnahmezeit</strong> läuft weiter. ${sync?'Aufnahmezeiten sind ab den protokollierten Sync-Punkten verfügbar.':'Noch kein Sync-Punkt gesetzt. Nutze vorerst Uhrzeit und Interviewzeit.'}</p><div class="button-row"><button id="csv-export" class="primary">CSV herunterladen</button><button id="edl-export" class="secondary">Resolve EDL</button><button id="txt-export" class="secondary">Lesbares Protokoll</button><button id="json-export" class="secondary">JSON</button><button id="share-export" class="secondary">Teilen / Dateien</button></div><div class="protocol"><table><thead><tr><th>Uhrzeit<br>Interview</th><th>Aufnahme</th><th>Frage / Ereignis</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${localTime(r.at)}<small>${fmt(r.activeMs)} aktiv</small></td><td>${r.recordingSeconds===null?'—':fmt(r.recordingSeconds*1000)}<small>${escapeHTML(r.syncId)}</small></td><td><strong>${r.type==='question'?escapeHTML(r.section):escapeHTML(r.type==='marker'?'⚑ Marker':eventName(r.type))}</strong>${r.type==='question'||r.label!==r.type?`<div>${escapeHTML(r.label)}</div>`:''}${r.type==='question'?`<small>Ende ${r.end?localTime(r.end):'offen'} · Dauer ${fmt(r.durationMs)}</small>`:''}${r.note?`<div class="log-note">${escapeHTML(r.note)}</div>`:''}${r.type==='marker'?`<button class="text-button" data-edit-marker="${r.at}">Beschriften</button>`:''}</td></tr>`).join(''):'<tr><td colspan="3">Das Protokoll beginnt mit dem Interviewstart.</td></tr>'}</tbody></table></div><div class="button-row"><button id="backup-export" class="secondary">Sitzungs-Backup sichern</button><button id="finish-early" class="text-button" ${!['running','paused'].includes(session.status)?'hidden':''}>Interview jetzt abschliessen</button></div><p class="modal-copy">Das Backup enthält zusätzlich den gesamten Sitzungsstand und lässt sich unter «Interview laden» wiederherstellen. CSV lässt sich in Excel öffnen. Das lesbare Protokoll ist eine Textdatei.</p>`);for(const [id,t] of [['csv-export','csv'],['txt-export','txt'],['json-export','json'],['backup-export','backup']])button(id,()=>exportFile(t));button('edl-export',showEDL);button('share-export',()=>exportFile('txt',true));button('finish-early',confirmFinish);$('modal-body').querySelectorAll('[data-edit-marker]').forEach(b=>b.onclick=()=>editMarker(Number(b.dataset.editMarker)));}
function editMarker(at){const e=session.events.find(x=>x.type==='marker'&&x.at===at);if(!e)return;modal('Clip-Marker beschriften',`<label for="marker-label">Kurzer Titel</label><input id="marker-label" type="text" maxlength="150" value="${escapeHTML(e.label)}"><label for="marker-note" style="margin-top:18px">Notiz</label><textarea id="marker-note" rows="3" maxlength="2000">${escapeHTML(e.note??'')}</textarea><div class="button-row"><button id="save-marker" class="primary">Sichern</button><button id="cancel-marker" class="secondary">Zurück</button></div>`);button('save-marker',()=>{mutate(()=>{e.label=$('marker-label').value.trim()||e.label;e.note=$('marker-note').value;});showLog();});button('cancel-marker',showLog);}
async function acquireWake(){if(!prefs.wake||session.status!=='running'||document.visibilityState!=='visible')return;if(!navigator.wakeLock)return;try{if(wakeLock&&!wakeLock.released)return;wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null;});}catch{ /* OS policy can deny; timing never depends on this. */ }}
function releaseWake(){wakeLock?.release().catch(()=>{});wakeLock=null;}
async function playSignal(log=true,offset=0){
 try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Audio nicht verfügbar');audioContext??=new AC();await audioContext.resume();if(audioContext.state!=='running')throw Error('Audio gesperrt');
  const t=audioContext.currentTime+.12,at=Date.now()+120;
  for(let i=0;i<3;i++){const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.connect(gain);gain.connect(audioContext.destination);osc.type='sine';osc.frequency.value=i===2?1600:900;const x=t+i*.25;gain.gain.setValueAtTime(0,x);gain.gain.linearRampToValueAtTime(.16,x+.007);gain.gain.setValueAtTime(.16,x+.055);gain.gain.linearRampToValueAtTime(0,x+.075);osc.start(x);osc.stop(x+.09);}
  setTimeout(()=>{$('flash').classList.add('on');setTimeout(()=>$('flash').classList.remove('on'),90);},120);
  if(log){mutate(()=>addSync(session,offset,at,'three_beeps_first_onset'));syncDialog('Sync-Punkt gesetzt. In der Aufnahme ist der BEGINN DES ERSTEN Tons die Referenz.');}else notify('Test: zwei kurze Töne und ein höherer Abschlusston.');
 }catch{notify('Kein Ton möglich. Lautstärke prüfen oder den manuellen Sync nutzen.');}}
function syncDialog(msg=''){const last=session.syncs.at(-1);modal('Aufnahme synchronisieren',`<p class="modal-copy">Starte zuerst Kamera und Audioaufnahme. Dann hört jedes Gerät denselben Sync-Ton. <strong>Der Beginn des ersten Tons</strong> ist eure Referenz beim Schnitt. Lautstärke am iPad vorher prüfen.</p>${msg?`<div class="message">${escapeHTML(msg)}</div>`:''}<div class="sync-card"><h3>♪ Ton + Lichtsignal</h3><p class="modal-copy">Drei kurze Töne und ein weisser Blitz. Nur auf Knopfdruck; während des Gesprächs gibt es keine automatischen Signaltöne.</p><button id="signal" class="primary" ${!['running','paused'].includes(session.status)?'disabled':''}>Sync-Ton auslösen</button><p class="modal-copy" style="margin-top:12px">Der neue Aufnahmeabschnitt beginnt hier bei 00:00. Die tatsächliche Datei kann früher begonnen haben. Den Videozeitcode am Sync-Punkt kannst du später korrigieren.</p></div><div class="sync-card"><h3>Manueller Sync / Klatschen</h3><p class="modal-copy">Bei einem Klatschen gleichzeitig tippen. Nutze das auch für neue Aufnahme-Dateien. Ohne Ton entsteht ein manueller Zeitanker.</p><button id="manual-sync" class="secondary" ${!['running','paused'].includes(session.status)?'disabled':''}>Jetzt manuellen Sync setzen</button></div>${last?`<div class="sync-card"><h3>Letzten Sync-Punkt abgleichen</h3><p class="modal-copy">${escapeHTML(last.id)} · ${localTime(last.at)} Uhr. Gib den Zeitcode dieses Moments in der Video-Datei an (MM:SS oder HH:MM:SS). Die Aufnahmezeiten ab diesem Punkt werden neu berechnet.</p><label for="video-offset">Videozeit beim Sync</label><input type="text" id="video-offset" inputmode="decimal" value="${fmt(last.offsetSeconds*1000)}" placeholder="00:12"><div class="button-row"><button id="offset-save" class="secondary">Zeitcode übernehmen</button></div></div>`:''}<p class="modal-copy">Orientierung für den Schnitt, keine framegenaue Timecode-Hardware. Audioausgabe und Reaktionszeit können leicht abweichen. Nach einer neuen Datei einen neuen Sync setzen. Bei Kopfhörern kann das Aufnahmegerät den Ton nicht hören.</p>`);button('signal',()=>playSignal(true));button('manual-sync',()=>{mutate(()=>addSync(session,0,Date.now(),'manual'));syncDialog('Manueller Sync-Punkt gesetzt.');});button('offset-save',()=>{const parts=$('video-offset').value.trim().split(':').map(Number);if(parts.length<2||parts.length>3||parts.some(x=>!Number.isFinite(x)||x<0)||parts.slice(1).some(x=>x>=60)){notify('Zeitcode als MM:SS oder HH:MM:SS eingeben.');return;}const sec=parts.reduce((n,x)=>n*60+x,0);mutate(()=>{last.offsetSeconds=sec;event(session,'sync_offset_changed',Date.now(),{syncId:last.id,offsetSeconds:sec});});syncDialog('Videozeitcode gespeichert.');});}
function confirmReset(){
 if(foreign){notify('Lade diesen Tab zuerst neu.');return;}
 modal('App aktualisieren und alles zurücksetzen?', `<p class="modal-copy">Der aktuelle Leitfaden wird durch den Standardleitfaden ersetzt. Protokoll, Marker, Notizen und Einstellungen werden auf diesem Gerät gelöscht. Ein exportiertes Sitzungs-Backup kannst du später wieder öffnen.</p><p id="reset-status" role="status" class="modal-copy"></p><div class="button-row"><button id="reset-cancel" class="secondary" autofocus>Abbrechen</button><button id="reset-backup" class="secondary">Sitzungs-Backup sichern</button><button id="reset-confirm" class="secondary">Alles zurücksetzen und neu laden</button></div>`);
 $('reset-cancel').focus();
 button('reset-cancel',showSettings);
 button('reset-backup',()=>exportFile('backup'));
 button('reset-confirm',resetAndReload);
}

function activateUpdate(worker){
 return new Promise((resolve,reject)=>{
  const timeout=setTimeout(()=>finish(Error('Die Aktualisierung dauert zu lange.')),30000);
  function finish(error){
   clearTimeout(timeout);
   worker.removeEventListener('statechange',check);
   if(error)reject(error);else resolve();
  }
  function check(){
   if(worker.state==='installed')worker.postMessage('activate-confirmed-update');
   if(worker.state==='activated')finish();
   if(worker.state==='redundant')finish(Error('Die neue Version konnte nicht installiert werden.'));
  }
  worker.addEventListener('statechange',check);
  check();
 });
}

async function resetAndReload(){
 const dialog=$('modal'), status=$('reset-status');
 const cancelClose=e=>e.preventDefault();
 dialog.addEventListener('cancel',cancelClose);
 dialog.querySelectorAll('button').forEach(b=>b.disabled=true);
 status.textContent='Aktuelle App und Standardleitfaden werden geprüft …';
 try{
  if('serviceWorker' in navigator){
   const reg=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});
   await reg.update();
   const worker=reg.installing||reg.waiting;
   if(worker)await activateUpdate(worker);
  }
  const response=await fetch('./interview.json',{cache:'reload'});
  if(!response.ok)throw Error();
  const fresh=freshSession(await response.json());
  if(foreign)throw Error();
  const previous=session;
  session=fresh;
  if(!save()){session=previous;throw Error();}
  localStorage.removeItem(PREF);
  foreign=true; // Prevent pagehide from writing during the reload.
  releaseWake();
  location.reload();
 }catch{
  status.textContent='Aktualisierung fehlgeschlagen. Prüfe Verbindung und lokalen Speicher. Bei mehreren Tabs öffne den aktuellen Interviewstand erneut.';
  dialog.querySelectorAll('button').forEach(b=>b.disabled=false);
 }finally{dialog.removeEventListener('cancel',cancelClose);}
}

function showSettings(){modal('Lesen & Einstellungen',`<div class="setting-row"><label for="font-size">Schriftgrösse <span id="font-value">${prefs.fontSize} px</span></label><input id="font-size" type="range" min="30" max="64" step="2" value="${prefs.fontSize}"></div><div class="setting-row"><label for="light-mode">Helles Erscheinungsbild</label><input id="light-mode" type="checkbox" ${prefs.light?'checked':''}></div><div class="setting-row"><label for="focus-mode">Fokusmodus <span>Weniger Hinweise, mehr Frage</span></label><input id="focus-mode" type="checkbox" ${prefs.focus?'checked':''}></div><div class="setting-row"><label for="hold-nav">Links / rechts halten <span>Fragenwechsel im Vollbildmodus</span></label><input id="hold-nav" type="checkbox" ${prefs.holdNav?'checked':''}></div><div class="setting-row"><label for="hold-ms">Haltezeit bis Fragenwechsel <span id="hold-value">${prefs.holdMs} ms</span></label><input id="hold-ms" type="range" min="300" max="2000" step="50" value="${prefs.holdMs}"></div><p class="modal-copy" id="hold-explanation">${holdExplanation()}</p><div class="setting-row"><label for="hold-haptics">Haptisches Feedback <span>${typeof navigator.vibrate==='function'?'Falls Vibrationshardware verfügbar':'Dieser Browser bietet keine Vibration an'}</span></label><input id="hold-haptics" type="checkbox" ${prefs.haptics?'checked':''}></div><div class="setting-row"><label for="wake-mode">Bildschirm wach halten <span>Wenn vom iPad unterstützt</span></label><input id="wake-mode" type="checkbox" ${prefs.wake?'checked':''}></div><p class="modal-copy" style="margin-top:18px">Eine Bildschirmsperre stoppt die Zeit nicht. Nur «Pause» hält das aktive Zeitbudget an. Die Aufnahmezeit läuft auch während einer Pause weiter.</p><div class="button-row"><button id="help-settings" class="secondary">Kurzanleitung</button><button id="backup-settings" class="secondary">Sitzungs-Backup</button><button id="load-settings" class="secondary">Interview laden</button></div><p class="modal-copy">${escapeHTML($('offline-state').textContent)}</p><p class="modal-copy">Tastatur: → nächste Frage · ← zurück · Leertaste Pause · M Clip-Marker. Im Textfeld bleiben diese Tasten normale Eingaben.</p><button id="reset-settings" class="secondary">App aktualisieren und zurücksetzen …</button>`);$('hold-nav').onchange=e=>{prefs.holdNav=e.target.checked;savePrefs();};$('hold-ms').oninput=e=>{prefs.holdMs=holdDuration(e.target.value);$('hold-value').textContent=prefs.holdMs+' ms';$('hold-explanation').textContent=holdExplanation();savePrefs();};$('hold-haptics').onchange=e=>{prefs.haptics=e.target.checked;savePrefs();};$('font-size').oninput=e=>{prefs.fontSize=Number(e.target.value);$('font-value').textContent=`${prefs.fontSize} px`;savePrefs();};$('light-mode').onchange=e=>{prefs.light=e.target.checked;savePrefs();};$('focus-mode').onchange=e=>{setFocus(e.target.checked);};$('wake-mode').onchange=e=>{prefs.wake=e.target.checked;savePrefs();if(prefs.wake)acquireWake();else releaseWake();};button('reset-settings',confirmReset);button('help-settings',showHelp);button('backup-settings',()=>exportFile('backup'));button('load-settings',showLibrary);}
function showHelp(){modal('Wenig tippen. Gut zuhören.',`<div class="modal-section"><h3>1 · Vorbereiten</h3><p class="modal-copy">Safari öffnen, Interview prüfen, Einverständnis und Technik klären. Über «Teilen → Zum Home-Bildschirm» lässt sich die App auf dem iPad ablegen. Einmal online öffnen und auf «Offline bereit» warten.</p></div><div class="modal-section"><h3>2 · Gespräch führen</h3><p class="modal-copy">«Interview starten» beginnt den geplanten Einstieg. «Erste Frage» und danach «Nächste Frage» protokollieren Beginn und Ende. Die Zeit läuft auch weiter, wenn das iPad gesperrt wird. Nur die Pausentaste stoppt die aktive Interviewzeit. Die Anzeige des Zeitplans vergleicht euren Fortschritt mit dem kumulierten Fragenbudget.</p></div><div class="modal-section"><h3>3 · Momente sichern</h3><p class="modal-copy">Für eure drei Präsentationsclips: Markiert eine konkrete Gesprächssituation, eine eigene Nachfrage und einen Moment, den ihr im Team reflektieren wollt. Tippe dafür direkt nach der Stelle auf «Clip markieren». Beschrifte ihn bei Bedarf später im Protokoll. Notizen gehören zur jeweiligen Frage. Über die Themenleiste kannst du einzelne Fragen überspringen oder erneut besuchen; jeder Besuch bleibt separat erhalten.</p></div><div class="modal-section"><h3>4 · Mit der Aufnahme abgleichen</h3><p class="modal-copy">Erst Aufnahmegeräte starten, dann Sync-Ton auslösen. Der erste Ton ist 00:00 des Aufnahmeabschnitts. Zeigt die Datei dort etwa 00:12, trage 00:12 beim Sync ein. Alle folgenden Aufnahmezeiten berücksichtigen diesen Versatz. Bei einer neuen Datei erneut synchronisieren.</p></div><div class="modal-section"><h3>5 · Exportieren</h3><p class="modal-copy">Am Ende CSV, JSON oder lesbaren Text exportieren. Ein Sitzungs-Backup kannst du zusätzlich auf ein anderes Gerät übertragen. Sitzungs-Backups sind beim Export eingefroren und werden pausiert wiederhergestellt. Daten bleiben in diesem Browser; kein Cloud-Abgleich. Löschen von Browserdaten, privates Surfen oder Speicherbereinigung können lokale Daten entfernen. Daher vor und nach dem echten Interview ein Backup sichern.</p></div><p class="message">Die App zeichnet selbst kein Audio oder Video auf. Bildschirmsperre, Ton und Offline-Verhalten bitte vor dem Interview auf eurem iPad testen.</p>`);}
function showLibrary(){modal('Interview laden',`<p class="modal-copy">Ein eigenes Interview als JSON hochladen oder ein Sitzungs-Backup wiederherstellen. Dein aktuelles Interview wird erst nach deiner Bestätigung ersetzt.</p><div class="button-row"><label class="file-label">JSON-Datei auswählen<input id="import-file" class="file-input" type="file" accept=".json,application/json"></label><button id="template-export" class="secondary">Aktuellen Leitfaden als JSON</button></div><div id="import-result"></div><div class="modal-section" style="margin-top:28px"><h3>Vor dem Wechsel</h3><p class="modal-copy">Sichere die aktuelle Sitzung, wenn du sie später wieder öffnen möchtest.</p><div class="button-row"><button id="library-backup" class="secondary">Aktuelle Sitzung sichern</button><button id="default-new" class="text-button">Standardinterview neu starten</button></div></div><p class="modal-copy">Format: version, title, guest, introSeconds, outroSeconds und sections mit questions. Jede Frage hat id, text, seconds, optionale followUps und transition. **Doppelte Sterne** markieren Betonungen. HTML wird als Text behandelt.</p>`);button('template-export',()=>exportFile('template'));button('library-backup',()=>exportFile('backup'));button('default-new',async()=>{try{const def=validateInterview(await (await fetch('./interview.json')).json());confirmNew(def);}catch{notify('Standardinterview gerade nicht verfügbar.');}});$('import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('Datei ist zu gross. Maximal 5 MB.');const raw=JSON.parse(await f.text());if(raw.format==='interview-cockpit-session'){importCandidate={kind:'session',value:validateSession(raw.session)};}else{importCandidate={kind:'interview',value:validateInterview(raw)};}const i=importCandidate.kind==='session'?importCandidate.value.interview:importCandidate.value;$('import-result').innerHTML=`<div class="message"><strong>${escapeHTML(i.title)}</strong><br>${escapeHTML(i.guest)} · ${i.sections.reduce((n,s)=>n+s.questions.length,0)} Fragen ${importCandidate.kind==='session'?'· gespeicherte Sitzung':''}</div><button id="confirm-import" class="primary">${importCandidate.kind==='session'?'Sitzung wiederherstellen':'Interview übernehmen'}</button>`;button('confirm-import',()=>confirmImport());}catch(err){$('import-result').innerHTML=`<div class="message error">${escapeHTML(err.message)}</div>`;importCandidate=null;}};}
function confirmNew(interview){importCandidate={kind:'interview',value:interview};confirmImport();}
function confirmImport(){if(!importCandidate)return;const candidate=importCandidate;modal('Aktuellen Stand ersetzen?',`<p class="modal-copy">${escapeHTML(candidate.kind==='session'?candidate.value.interview.title:candidate.value.title)} wird geladen. Der bisherige Stand in diesem Browser wird ersetzt. Sichere ihn zuerst, wenn du ihn behalten möchtest.</p><div class="button-row"><button id="before-replace" class="secondary">Bisherige Sitzung sichern</button><button id="replace-now" class="primary">Jetzt übernehmen</button><button id="cancel-replace" class="text-button">Abbrechen</button></div>`);button('before-replace',()=>exportFile('backup'));button('cancel-replace',closeModal);button('replace-now',()=>{if(foreign)return;releaseWake();session=candidate.kind==='session'?candidate.value:freshSession(candidate.value);if(candidate.kind==='session'&&session.status==='running')pause(session);noteOpen=false;followOpen=true;$('resume-banner').hidden=true;save();render();closeModal();notify(candidate.kind==='session'?'Sitzung wiederhergestellt. Laufende Backups sind zunächst pausiert.':'Interview ist bereit.');});}
button('settings-btn',showSettings);button('log-btn',showLog);button('library-btn',showLibrary);button('close-modal',closeModal);button('focus-btn',()=>setFocus(!prefs.focus));button('back-btn',()=>navigate(session.current-1));button('next-btn',()=>{if(session.current===stepsFor(session.interview).length-1)confirmFinish();else navigate(session.current+1);});button('pause-btn',()=>{mutate(()=>session.status==='running'?pause(session):resume(session));if(session.status==='running')acquireWake();else releaseWake();});button('focus-pause-btn',()=>{$('pause-btn').click();});button('clip-btn',mark);button('sync-btn',()=>syncDialog());button('followup-toggle',()=>{followOpen=!followOpen;render();});button('note-btn',()=>{noteOpen=!noteOpen;$('note-area').hidden=!noteOpen;if(noteOpen)$('question-note').focus();requestAnimationFrame(fitFocusQuestion);});button('dismiss-resume',()=>{$('resume-banner').hidden=true;});
$('question-note').addEventListener('input',e=>{if(foreign)return;session.notes[stepsFor(session.interview)[session.current].id]=e.target.value;save();});
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||$('modal').open||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)||!['running','paused'].includes(session?.status)||e.repeat)return;if(['ArrowRight','ArrowLeft',' ','m','M'].includes(e.key))e.preventDefault();if(e.key==='ArrowRight')$('next-btn').click();if(e.key==='ArrowLeft')$('back-btn').click();if(e.key===' ')$('pause-btn').click();if(e.key.toLowerCase()==='m')mark();});
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===KEY+':backup'){const next=unpack(e.newValue);if(next&&next.writer!==writer&&next.revision>revision){foreign=true;lockWarning();}}});
document.addEventListener('visibilitychange',()=>{if(!session)return;if(document.visibilityState==='hidden'){if(['running','paused'].includes(session.status)&&!foreign){event(session,'screen_hidden');save();}}else{if(['running','paused'].includes(session.status)&&!foreign){event(session,'screen_visible');save();tick();acquireWake();}}});
window.addEventListener('pagehide',()=>{if(session&&!foreign)save();});window.addEventListener('pageshow',()=>{if(session){tick();acquireWake();}});
async function offlineSetup(){if(!('serviceWorker'in navigator)||location.protocol==='file:'){$('offline-state').textContent='○ Offline-Modus benötigt HTTPS';return;}try{const reg=await navigator.serviceWorker.register('./sw.js',{scope:'./'});await navigator.serviceWorker.ready;$('offline-state').textContent='● Offline bereit';if($('setup-offline'))$('setup-offline').textContent='● Offline bereit';reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)notify('Eine App-Aktualisierung ist nach dem Interview verfügbar.');});});}catch{$('offline-state').textContent='○ Offline-Vorbereitung fehlgeschlagen';if($('setup-offline'))$('setup-offline').textContent=$('offline-state').textContent;}}
async function boot(){try{const p=JSON.parse(localStorage.getItem(PREF));if(p){prefs={fontSize:Math.max(30,Math.min(64,Number(p.fontSize)||42)),light:p.light===true,focus:p.focus===true,wake:p.wake!==false,holdNav:p.holdNav!==false,holdMs:holdDuration(p.holdMs??600),haptics:p.haptics!==false};}const loaded=readStore();if(loaded.value){session=loaded.value.session;revision=loaded.value.revision;if(['running','paused'].includes(session.status))$('resume-banner').hidden=false;}else if(loaded.damaged){throw Error('corrupt');}}catch(e){storageWarning(e.message==='corrupt'?'Der gespeicherte Stand ist beschädigt. Er wurde nicht überschrieben. Lade ein Sitzungs-Backup über «Interview laden».':'Lokaler Speicher nicht verfügbar. Bitte vor einem echten Interview ein Backup testen.');}
 if(!session){try{const res=await fetch('./interview.json');if(!res.ok)throw Error();session=freshSession(await res.json());}catch{$('setup').innerHTML='<h2>Leitfaden nicht geladen</h2><p>Bitte die vollständige App über GitHub Pages öffnen und neu laden.</p>';$('library-btn').onclick=()=>notify('Bitte zunächst den Standardleitfaden laden.');return;}}
 render();if(!storageFailed)save();offlineSetup();acquireWake();setInterval(tick,250);}
const holdNavigation=installHoldNavigation({
 enabled:()=>prefs.focus&&prefs.holdNav&&!foreign&&!$('modal').open&&['running','paused'].includes(session?.status),
 duration:()=>prefs.holdMs,haptics:()=>prefs.haptics,canGoBack:()=>session.current>0,
 onNavigate:direction=>$(direction>0?'next-btn':'back-btn').click()
});
function holdExplanation(){return `Rechts halten: weiter. Links halten: zurück. Kreis voll nach ${prefs.holdMs-250} ms, danach bleiben mindestens 250 ms zum Loslassen und Abbrechen. Wegziehen, Scrollen oder eine zweite Berührung brechen ebenfalls ab. Pro Berührung höchstens ein Wechsel. Buttons bleiben normal bedienbar. Kurze Vibration bei vollem Kreis und beim Wechsel, sofern unterstützt.`;}
boot();

function showEDL(){
 let rows=parseCockpitCSV(csvFor(session)),source='Aktuelles Interview';
 modal('Marker für DaVinci Resolve',`<p class="modal-copy">Direkt als Marker-EDL herunterladen oder ein früheres Cockpit-CSV umwandeln. Die Sitzung bleibt erhalten.</p><div class="button-row"><label class="secondary" for="edl-csv">CSV-Datei laden</label><input id="edl-csv" type="file" accept=".csv,text/csv" style="max-width:100%"></div><p id="edl-source" class="modal-copy"></p><label for="edl-sync">Aufnahmesegment / Sync-Punkt</label><select id="edl-sync"></select><div class="edl-grid"><div><label for="edl-fps">Bildrate der Resolve-Timeline</label><select id="edl-fps">${Object.keys(FRAME_RATES).map(k=>`<option value="${k}" ${k==='25'?'selected':''}>${k.replace('df','')} fps · ${k.endsWith('df')?'Drop Frame':'Non-Drop Frame'}</option>`).join('')}</select></div><div><label for="edl-start">Start-Timecode der Timeline</label><input id="edl-start" value="01:00:00:00" inputmode="text"></div></div><label for="edl-anchor">Timeline-Timecode beim ersten Sync-Ton</label><input id="edl-anchor" value="01:00:00:00" inputmode="text"><p class="modal-copy">In Resolve den Abspielkopf auf den Beginn des Sync-Tons setzen und dessen Timecode übernehmen (HH:MM:SS:FF). Der vorgeschlagene Wert nimmt an, dass die Aufnahme am Timeline-Anfang liegt. Bei mehreren Aufnahmen jedes Segment separat exportieren.</p><label class="checkline"><input id="edl-ranges" type="checkbox" checked> Fragen als Bereichsmarker (Beginn bis Ende)</label><label class="checkline"><input id="edl-clips" type="checkbox" checked> Clip-Marker einschliessen</label><p id="edl-status" class="modal-copy" role="status"></p><div class="button-row"><button id="edl-download" class="primary">EDL herunterladen</button><button id="edl-back" class="secondary">Zurück zum Protokoll</button></div><p class="modal-copy">Resolve: Timeline im Media Pool rechts anklicken → Timelines → Import → Timeline Markers from EDL. Nicht als neue Timeline importieren. Fragen sind blau, Clip-Marker gelb. Bestehende Marker an denselben Positionen vorher prüfen.</p>`);
 function options(){const syncs=csvSyncs(rows);$('edl-sync').innerHTML=syncs.map(x=>`<option value="${escapeHTML(x.id)}">${escapeHTML(x.id)} · ${escapeHTML(x.recording)} Aufnahme</option>`).join('');$('edl-source').textContent=source;propose();}
 function propose(){try{const sync=csvSyncs(rows).find(x=>x.id===$('edl-sync').value),fps=$('edl-fps').value,parts=(sync?.recording||'00:00').split(':').map(Number),seconds=parts.reduce((n,x)=>n*60+x,0);$('edl-anchor').value=framesTC(tcFrames($('edl-start').value,fps)+Math.round(seconds*FRAME_RATES[fps].fps),fps);}catch{}preview();}
 function build(){return resolveEDL(rows,{fps:$('edl-fps').value,syncId:$('edl-sync').value,timelineStart:$('edl-start').value,syncTimecode:$('edl-anchor').value,ranges:$('edl-ranges').checked,clips:$('edl-clips').checked,title:source});}
 function preview(){try{const r=build();$('edl-status').textContent=`${r.count} Marker bereit. ${r.skipped} Einträge ausserhalb dieses Segments oder vor dem Timeline-Anfang ausgelassen.${r.points?' '+r.points+' offene oder segmentübergreifende Fragen erhalten einen Punktmarker.':''} Pausen bleiben in der Aufnahmezeit enthalten.`;$('edl-download').disabled=false;}catch(e){$('edl-status').textContent=e.message;$('edl-download').disabled=true;}}
 $('edl-csv').onchange=async()=>{const f=$('edl-csv').files[0];if(!f)return;try{if(f.size>10000000)throw Error('CSV ist zu gross (max. 10 MB).');const parsed=parseCockpitCSV(await f.text());rows=parsed;source=f.name;options();}catch(e){$('edl-status').textContent=e.message;$('edl-download').disabled=true;}};
 for(const id of ['edl-sync','edl-fps','edl-start'])$(id).addEventListener('change',propose);
 for(const id of ['edl-anchor','edl-ranges','edl-clips'])$(id).addEventListener('input',preview);
 button('edl-back',showLog);button('edl-download',()=>{try{const r=build(),url=URL.createObjectURL(new Blob([r.text],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=`Interview_${$('edl-sync').value.replace(/[^a-zA-Z0-9_-]/g,'_')}.edl`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Resolve-Marker-EDL erstellt.');}catch(e){notify(e.message);}});options();
}

function renderSectionProgress(q,done){
 const model=sectionProgress(session.interview,q.id,done),bar=$('focus-section-progress');
 bar.innerHTML=model.sections.map(s=>`<div class="section-progress-group" style="--group-size:${s.questions.length};--group-color:${s.color};--group-rgb:${rgb(s.color)}" title="${escapeHTML(s.id+' · '+s.title)}">${s.questions.map(item=>`<span class="section-progress-question ${item.completed?'completed':''} ${item.current?'current':''}" ${item.current?'aria-current="step"':''}><span class="question-dot"></span></span>`).join('')}</div>`).join('');
 bar.setAttribute('aria-valuenow',String(Math.round(model.completed/model.total*100)));
 bar.setAttribute('aria-valuetext',`${model.completed} von ${model.total} Fragen abgeschlossen${model.active?', Bereich '+model.active.id+', Frage '+model.position+' von '+model.active.questions.length:''}`);
 $('focus-section-position').textContent=model.active?`${model.position} / ${model.active.questions.length} im Bereich`:'';
 const next=model.next;$('handoff-notice').hidden=!next;$('focus-handoff-edge').hidden=!next;
 if(next){$('handoff-notice').textContent=`Danach ${next.id} · Übergabe →`;$('handoff-notice').title=`Nach dieser Frage: Bereich ${next.id} · ${next.title}. Übergabe im Interviewteam vorbereiten.`;for(const el of [$('handoff-notice'),$('focus-handoff-edge')]){el.style.setProperty('--next-color',next.color);el.style.setProperty('--next-rgb',rgb(next.color));}}
}
